2	
3	import com.maritime.platform.gateway.security.GatewayPrincipal;
4	import com.maritime.platform.gateway.security.GatewaySecurityProperties;
5	import io.jsonwebtoken.Claims;
6	import io.jsonwebtoken.ExpiredJwtException;
7	import io.jsonwebtoken.Jws;
8	import io.jsonwebtoken.Jwts;
9	import io.jsonwebtoken.security.Keys;
10	import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
11	import org.springframework.stereotype.Component;
12	import org.springframework.util.StringUtils;
13	import reactor.core.publisher.Mono;
14	
15	import javax.crypto.SecretKey;
16	import java.nio.charset.StandardCharsets;
17	import java.time.Clock;
18	import java.time.Instant;
19	import java.util.Date;
20	
21	/**
22	 * Extracts, decrypts, verifies and maps JWT tokens to
23	 * {@link GatewayPrincipal.User} instances.
24	 *
25	 * <p>All operations run via {@link Mono#fromCallable}, keeping
26	 * the non-blocking gateway event loop free.
27	 */
28	@Component
29	@ConditionalOnProperty("maritime.gateway.security.jwt.enabled")
30	public class JwtAuthenticationManager {
31	
32		private final GatewaySecurityProperties.Jwt jwtConfig;
33		private final SecretKey signingKey;
34		private final JwtEncryptor encryptor;
35		private final JwtClaimsMapper claimsMapper;
36		private final Clock clock;
37	
38		public JwtAuthenticationManager(GatewaySecurityProperties properties, JwtClaimsMapper claimsMapper) {
39			this(properties, claimsMapper, Clock.systemUTC());
40		}
41	
42		JwtAuthenticationManager(GatewaySecurityProperties properties, JwtClaimsMapper claimsMapper, Clock clock) {
43			this.jwtConfig = properties.getJwt();
44			this.signingKey = Keys.hmacShaKeyFor(jwtConfig.getSecret().getBytes(StandardCharsets.UTF_8));
45			this.encryptor = jwtConfig.isEncrypted() ? new JwtEncryptor(jwtConfig.getSecret()) : null;
46			this.claimsMapper = claimsMapper;
47			this.clock = clock;
48		}
49	
50		/**
51		 * Authenticate the given token string, returning a mapped user principal
52		 * or an error signal carrying a {@link JwtAuthenticationException}.
53		 */
54		public Mono<GatewayPrincipal.User> authenticate(String token) {
55			return Mono.fromCallable(() -> doAuthenticate(token));
56		}
57	
58		private GatewayPrincipal.User doAuthenticate(String token) {
59			String rawToken = decryptIfNeeded(token);
60			Claims claims = parseAndValidate(rawToken);
61			GatewayPrincipal.User user = claimsMapper.map(claims);
62			validateRequiredClaims(user);
63			return user;
64		}
65	
66		private String decryptIfNeeded(String token) {
67			if (encryptor == null) {
68				return token;
69			}
70			String decrypted = encryptor.decrypt(token);
71			if (decrypted == null) {
72				throw new JwtAuthenticationException(GatewayAuthErrorCode.INVALID_TOKEN,
73						"Token decryption failed");
74			}
75			return decrypted;
76		}
77	
78		private Claims parseAndValidate(String token) {
79			try {
80				Jws<Claims> jws = Jwts.parser()
81						.verifyWith(signingKey)
82						.clockSkewSeconds(jwtConfig.getClockSkewSeconds())
83						.clock(() -> Date.from(clock.instant()))
84						.build()
85						.parseSignedClaims(token);
86	
87				Claims claims = jws.getPayload();
88	
89				String issuer = claims.getIssuer();
90				if (!jwtConfig.getIssuer().equals(issuer)) {
91					throw new JwtAuthenticationException(GatewayAuthErrorCode.INVALID_TOKEN,
92							"Invalid issuer: " + issuer);
93				}
94	
95				Date expiration = claims.getExpiration();
96				if (expiration != null) {
97					Instant expiryInstant = expiration.toInstant();
98					Instant threshold = clock.instant().minusSeconds(jwtConfig.getClockSkewSeconds());
99					if (expiryInstant.isBefore(threshold)) {
100						throw new JwtAuthenticationException(GatewayAuthErrorCode.TOKEN_EXPIRED,
101								"Token expired at " + expiration);
102					}
103				}
104	
105				return claims;
106			} catch (ExpiredJwtException e) {
107				throw new JwtAuthenticationException(GatewayAuthErrorCode.TOKEN_EXPIRED, e.getMessage());
108			} catch (JwtAuthenticationException e) {
109				throw e;
110			} catch (Exception e) {
111				throw new JwtAuthenticationException(GatewayAuthErrorCode.INVALID_TOKEN, e.getMessage());
112			}
113		}
114	
115		private void validateRequiredClaims(GatewayPrincipal.User user) {
116			if (!StringUtils.hasText(user.userId())) {
117				throw new JwtAuthenticationException(GatewayAuthErrorCode.INVALID_TOKEN,
118						"Required claim '" + jwtConfig.getClaims().getUserId() + "' is missing or empty");
119			}
120			if (!StringUtils.hasText(user.sessionId())) {
121				throw new JwtAuthenticationException(GatewayAuthErrorCode.INVALID_TOKEN,
122						"Required claim '" + jwtConfig.getClaims().getSessionId() + "' is missing or empty");
123			}
124		}
125	}
