			String token = Jwts.builder()
					.issuer(ISSUER)
					.id(jti)
					.claim("userId", "user-123")
					.claim("sessionId", "session-abc")
					.issuedAt(Date.from(now))
					.expiration(Date.from(now.plus(1, ChronoUnit.HOURS)))
