		}

		@Test
		@DisplayName("empty userId string produces INVALID_TOKEN")
		void emptyUserIdIsInvalid() {
			Instant now = Instant.now();
			String token = Jwts.builder()
					.issuer(ISSUER)
					.claim("userId", "")
					.claim("sessionId", "session-abc")
