	// ---------- encrypted JWT ----------

	@Nested
	@DisplayName("Encrypted JWT")
	class EncryptedJwt {

		@Test
		@DisplayName("decrypts encrypted token and authenticates successfully")
		void decryptsAndAuthenticates() {
