			JwtStateValidator stateValidator = Mockito.mock(JwtStateValidator.class);
			when(stateValidator.validate(any(), any(), any())).thenReturn(Mono.empty());

			JwtAuthenticationManager mgr = new JwtAuthenticationManager(
